# Bám sách: trang 124–125 + đáp án + Mini dictionary unit 60. Không chép nguyên văn.
theory = (
 H("A", "Typical meanings of take in phrasal verbs", "Các nghĩa thường gặp của take trong phrasal verb")
 + P("<i>Take</i> often means ‘remove’: happy memories can be <b>taken away</b> from a holiday; Phil may be <b>taken off</b> night work by his boss; Helena <b>took</b> her parents <b>out</b> to eat (Unit 42).", "<i>Take</i> thường mang nghĩa ‘lấy đi, đưa đi’: bạn <b>mang về</b> những kỷ niệm đẹp sau kỳ nghỉ; sếp đồng ý <b>cho</b> Phil <b>thôi</b> làm ca đêm; Helena <b>đưa</b> bố mẹ <b>đi</b> ăn (bài 42).")
 + P("It can also mean doing something, or something happening, quickly or suddenly: <b>Take it away!</b> (Unit 30), <b>take aback</b> (surprise), <b>take off</b> (a plane leaving the ground), <b>take out</b> (destroy in war).", "<i>Take</i> còn mang nghĩa làm gì, hay việc gì xảy ra, nhanh hoặc đột ngột: <b>Take it away!</b> (bài 30), <b>take aback</b> (làm sửng sốt), <b>take off</b> (máy bay cất cánh), <b>take out</b> (tiêu diệt trong trận chiến).")
 + H("B", "Organising a charity concert", "Tổ chức một buổi hòa nhạc từ thiện")
 + P("The organiser of a charity concert looks back on the experience.", "Người tổ chức một buổi hòa nhạc từ thiện nhìn lại trải nghiệm của mình.")
 + T([
    ("<b>take aback</b>", "The organiser was very surprised by the cost.", "Người tổ chức sửng sốt trước chi phí."),
    ("<b>take up</b>", "A huge amount of time was used on phone calls to persuade sponsors.", "Rất nhiều thời gian bị ngốn vào các cuộc gọi thuyết phục nhà tài trợ."),
    ("<b>uptake</b>", "At first few sponsors committed themselves, but slowly companies and individuals agreed.", "Lúc đầu ít người cam kết tài trợ, nhưng dần dần các công ty và cá nhân đã đồng ý."),
    ("<b>take down</b>", "After the concert, it took a whole day to remove the stage set and lighting in pieces.", "Sau buổi hòa nhạc, mất cả ngày để tháo dỡ sân khấu và hệ thống đèn."),
    ("<b>take away from</b>", "None of that made the pleasure of organising it seem less.", "Không điều gì làm giảm niềm vui khi tổ chức buổi diễn."),
    ("<b>take away</b>", "The audience will remember something from it for a long time.", "Khán giả sẽ còn nhớ mãi điều gì đó từ buổi diễn."),
 ])
 + H("C", "Other phrasal verbs with take", "Các phrasal verb khác với take")
 + T([
    ("<b>take</b> sb <b>away</b>", "Take someone to a different place: he took his mum to the coast for a week.", "Đưa ai đi nơi khác: anh đưa mẹ ra biển một tuần."),
    ("<b>take</b> sb <b>off</b> sth", "Remove someone from a job (a security chief who was not strict enough), or stop giving someone a medicine (pills that made her sick).", "Cho ai thôi một việc (trưởng bảo vệ không đủ nghiêm), hoặc ngừng cho ai dùng một loại thuốc (thuốc làm cô ấy buồn nôn)."),
    ("<b>take up</b>", "Discuss or deal with something: a tutor will raise a problem with the Head of Department.", "Bàn hoặc giải quyết việc gì: gia sư sẽ nêu vấn đề với trưởng khoa."),
    ("<b>take along</b>", "Take something with you, such as an umbrella.", "Mang theo thứ gì, như cái ô."),
    ("<b>intake</b>", "The number of people accepted at one time, e.g. by a college: this year’s group has better grades.", "Số người được nhận vào một đợt, ví dụ ở trường đại học: khóa năm nay điểm cao hơn."),
    ("<b>take-off</b>", "An imitation: she does a brilliant one of Adele.", "Màn nhại: cô ấy nhại Adele tài tình."),
 ])
 + NOTE("<b>Over to you</b>: if you have finished all the units in the book, congratulations! Revise the phrasal verbs regularly and try to use them when you speak and write.",
        "<b>Over to you</b>: nếu bạn đã học xong mọi bài trong sách, xin chúc mừng! Hãy ôn lại các phrasal verb thường xuyên và cố dùng chúng khi nói và viết.")
)
